def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the regularly repeated separator rows and columns.
    rows = [r for r in range(h) if sum(v == bg for v in grid[r]) > w * 0.65]
    cols = [c for c in range(w) if sum(grid[r][c] == bg for r in range(h)) > h * 0.65]

    # The non-background cell repeated through the tile interiors is the
    # default output color; special colors at separator crossings are retained.
    inner_counts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                inner_counts[grid[r][c]] = inner_counts.get(grid[r][c], 0) + 1
    base = max(inner_counts, key=inner_counts.get) if inner_counts else bg

    out = []
    for r in rows:
        line = []
        for c in cols:
            v = grid[r][c]
            line.append(base if v == bg else v)
        out.append(line)
    return out
